import React from 'react';

const graphStyle={
    "width":"100%",
    "height":"100%"
}
const Desmos = window.Desmos;

class Graph extends React.Component{
    constructor(props){
        super(props);
        this.graphRef = React.createRef();
        // this.state = {
        //     calculator:undefined,
        // }
        this.calculator =undefined;
    }

    componentDidMount(){
        // console.log("rendering graph....");
        const graph = this.graphRef.current;
        const options={
            "expressions":false,
            // "settingsMenu":false,
            "zoomButtons":false,
        };
        this.calculator= Desmos.GraphingCalculator(graph,options);

    }

    componentDidUpdate(props){
            this.calculator.setBlank();
            this.props.exp.forEach(function(item){
                if(item.plot){
                    this.calculator.setExpression({id:item.plotID,latex:String.raw`${item.outLatex}`,color:item.color});
                }
            }.bind(this));
    }
    render(){
        return (
            <div id="graph-container" style={graphStyle} ref={this.graphRef}></div>
        );
    }
}

export default Graph;