  //              SlateGray,     Red,  SaddleBrown, Purple,     Black,    Green,     Olive,    Maroon,  CadetBlue,  ScrollBlue
  global.Color =["#708090",  "#ff0000", "#8b4513", "#800080", "#000000","#006400", "#808000","#800000", "#5f9ea0",   "#2c4870"];
  global._plotID = 0;

class MathExpression{
  constructor(expression,sympyExpression=null,type=null,input=null,inputType=null,color="#ffffff"){
    this.input = input;
    this.inputType = inputType;
    this.sympyExpression =sympyExpression;
    this.outLatex = expression;
    this.type = type;
    global._plotID += 1;
    this.plot=false;
    this.plotID = global._plotID.toString();
    this.color= color;
    this.expressionShow = true;
    // if(global.Color.length == 0){
    //   this.color = color;
    //   this.plot =false;
    // }
    // else{
    //   this.color = global.Color.pop();
    // }
  }
  togglePlot(){
    if(!this.plot){
      if(global.Color.length === 0){
        console.log("Cannot Plot more Than ten Equations!!");
        console.log("UnPlot an Exression and try again");
        return this;
      }
      this.color = global.Color.pop();
      this.plot = true;
    }
    else{
      global.Color.push(this.color);
      this.color="#ffffff";
      this.plot=false;
    }
    return this;
  }


}
