import React  from 'react';
import * as iink from 'iink-js';
import Pen from "./assets/cursors/Pen.cur"
import IconButton from '@material-ui/core/IconButton';
import DeleteIcon from '@material-ui/icons/Delete';
import UndoIcon from '@material-ui/icons/Undo'
import RedoIcon from '@material-ui/icons/Redo'
import Tooltip from '@material-ui/core/Tooltip';

class Editor extends React.Component {

    editorRef = this.current;
    constructor(props){
        super(props);
        this.editorStyle = {
            // 'minWidth': '100px',
            // 'minHeight': '100px',
            'width': '100%',
            'height': '100%',
            'touchAction': 'none',
            'backgroundColor': 'white',
            'borderRadius':'4px',
            // 'cursor':`url(${Pen}),auto`,
            'touchAction':'none',
        }
        this.editorRef = this.props.editorRef;
        this.state = {
            undoDisabled:true,
            redoDisabled:true,
            clearDisabled:true,
        };
        this._ismounted = false;
        this.editorClear = this.editorClear.bind(this);
        this.editorRedo = this.editorRedo.bind(this);
        this.editorUndo = this.editorUndo.bind(this);
        this.handleKeyDown = this.handleKeyDown.bind(this);
    }

    componentDidMount(){   
        this._ismounted = true;
        var editor = this.editorRef.current;
        editor = iink.register(editor,{
            triggerDelay:500,
            triggers: {
                exportContent: 'QUIET_PERIOD'
              },
            recognitionParams: {
                type: 'MATH',
                protocol: 'WEBSOCKET',
                apiVersion: 'V4',
                server: {
                    scheme: 'https',
                    host: 'webdemoapi.myscript.com',
                    applicationKey: 'ce077853-2bbb-4d4c-8b65-77bea3bfa52b',
                    hmacKey: '4a48df9c-66e1-47d5-aaaf-f01e2dae4279',
                },
                iink: {
                    math: {
                      mimeTypes: ['application/x-latex'],
                      solver:{
                          enable:false,
                      }
                    },
                    export: {
                        jiix: {
                          strokes: true
                        }
                    }
                }
            },
        });
   
        this.editorRef.current.addEventListener('changed', (event) => {
            this.setState({undoDisabled : !event.detail.canUndo}) ;
            this.setState({redoDisabled : !event.detail.canRedo}) ;  
            this.setState({clearDisabled : event.detail.isEmpty});
        });
        this.editorRef.current.addEventListener("keydown",function(event){

        })
        window.addEventListener('resize',function(evt){
            editor.resize();
        });

    }

    editorUndo(){
        if(this._ismounted)
            this.editorRef.current.editor.undo();
    }
    editorRedo(){
        if(this._ismounted)
            this.editorRef.current.editor.redo();
    }
    editorClear(){
        if(this._ismounted)
            this.editorRef.current.editor.clear();
    }
    componentWillUnmount(){
        this._ismounted = false;
        this.editorRef.current.editor.close();
    }
    handleKeyDown(event){
            console.log(event);
            if(event.ctrlKey && event.key === 'z'){
                this.editorUndo();
            }
            else if(event.ctrlKey && event.key === 'y')
                this.editorRedo();
            else if(event.keyCode === 46)
                this.editorClear();
    }
  
    render()
    {
        return(   
            <div style={{position:"relative",width:"100%",height:"100%"}} tabIndex="-1" onKeyDown={this.handleKeyDown}>     
                <div style={this.editorStyle} ref={this.editorRef} touch-action="none"></div>
                {this.props.buttons &&
                (<div style={{position:"absolute",top:"1px",right:"1px",zIndex:"25"}}>
                    <Tooltip title="Undo">
                        <span>
                        <IconButton id="undo"variant="contained" color="primary" size="small" style={{margin:"3px"}} onClick={this.editorUndo} disabled={this.state.undoDisabled}>
                            <UndoIcon fontSize={this.props.size}/>
                        </IconButton>
                        </span>
                    </Tooltip>
                    <Tooltip title="Redo">
                        <span>
                        <IconButton id="redo" variant="contained" color="primary" size="small" style={{margin:"3px"}} onClick={this.editorRedo} disabled={this.state.redoDisabled}>
                            <RedoIcon fontSize={this.props.size}/>
                        </IconButton>
                        </span>
                    </Tooltip>
                    <Tooltip title="Clear">
                        <span>
                        <IconButton id="clear" variant="contained" color="primary" size="small" style={{margin:"3px"}} onClick={this.editorClear} disabled={this.state.clearDisabled}>
                            <DeleteIcon fontSize={this.props.size}/>                   
                        </IconButton>
                        </span> 
                    </Tooltip>
            
                </div>)}
            </div>
        );
    }

}

Editor.defaultProps={
    size : "default",
}

export default React.forwardRef((props,ref) => <Editor editorRef={ref} {...props}/>);
