import React,{useRef}  from 'react';
import { BlockMath } from 'react-katex';
import IconButton from '@material-ui/core/IconButton';
// import Menu from '@material-ui/core/Menu';
// import MenuItem from '@material-ui/core/MenuItem';
import MoreVertIcon from '@material-ui/icons/MoreVert';
// import {Icon} from '@material-ui/core';
import {SvgIcon} from '@material-ui/core';
import Tooltip from '@material-ui/core/Tooltip';
import Snackbar from '@material-ui/core/Snackbar';
import Menu from '@material-ui/core/Menu';
import MenuItem from '@material-ui/core/MenuItem';
import { makeStyles } from '@material-ui/core/styles';
// import Paper from '@material-ui/core/Paper';
import Card from '@material-ui/core/Card';

// import PopupState, { bindTrigger, bindMenu } from 'material-ui-popup-state';


function Expression(props){
 
    let ExpressionStyle={
        // "resize": "vertical",
        "position":"relative",
        "backgroundColor":`${props.exp.color}2c`,
        // "boxSizing":"border-box",
        "width":"calc(100% - 8px)",
        "left":"2px",
        "height":"auto",
        "minHeight": "100px",
        "maxHeight": "300px",
        "margin":"2px",
        "display": "flex",
        "flexDirection":"row",
        "whiteSpace":"no-wrap",
    };
    const [state, setState] = React.useState({
        open: false,
      });
    const moreRef = useRef(null);
    const [moreOptions,moreOptionsState] = React.useState(null);
    const moreClick=function(evt){
        moreOptionsState(moreRef.current);
    }

    const moreClose=function(evt){
        moreOptionsState(null);
    }

    if(props.exp.expressionShow)
        return (
            
            <Card className="solution" style={ExpressionStyle} elevation={2}>
                <div style={{width:"12px",height:"100%",backgroundColor:props.exp.color}}></div>
                <div className="solution-katex" style={{width:"calc(100% - 64px)",height:"auto",overflow:"scroll auto",scrollBehavior:"smooth",scrollbarWidth:"thin"}}>
                    <BlockMath math={props.exp.outLatex} />
                </div>
                <div style={{display:"flex",flexDirection:"column",justifyContent:"flex-start" }}>
                    <Tooltip title="More Options" placement="bottom">
                        <span>
                        <IconButton  ref={moreRef} onClick={moreClick}>
                            <MoreVertIcon size="small"></MoreVertIcon>
                        </IconButton>
                        </span>

                    </Tooltip>
                    <Tooltip title="Copy" placement="bottom">
                        <span>
                            <IconButton 
                                onClick={
                                    () => {
                                        navigator.clipboard.writeText(props.exp.outLatex);
                                        setState({open:true})
                                    }}>
                                <SvgIcon style={{width:"25px",height:"25px"}}>
                                    <path d="M0 0h24v24H0z" fill="none"/><path d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z"/>
                                </SvgIcon>
                            </IconButton>
                        </span>

                    </Tooltip>
                </div>
                <Menu
                anchorEl={moreOptions}
                getContentAnchorEl={null}
                anchorOrigin={{
                vertical: 'bottom',
                horizontal: 'center',
                }}
                transformOrigin={{
                vertical: 'top',
                horizontal: 'center',
                }}
                open={Boolean(moreOptions)}
                onClose={moreClose}>
                    <MenuItem key={"Operate"} onClick={()=>{props.operateClick();moreClose()}} onClose={moreClose}>Operate</MenuItem>
                    <MenuItem key={"Plot"} onClick={()=>{props.plotClick();moreClose()}} onClose={moreClose}>{!props.exp.plot && "Plot"}{props.exp.plot && "Unplot"}</MenuItem>
                    <MenuItem key={"Delete"} onClick={()=>{props.deleteClick();moreClose()}} onClose={moreClose}>Delete</MenuItem>
                </Menu>
                <Snackbar
                    anchorOrigin={{vertical:"bottom",horizontal:"center"}}
                    open={state.open}
                    onClose={()=>{setState({open:false})}}
                    message="Copied LaTeX!!"
                    key="vertical + horizontal"
                    autoHideDuration={1000}
                />
            </Card>
        );
        
}


export default Expression;